INSERT OR IGNORE INTO projects (id, sort, title, role, duration, short, description, tech, color, repo) VALUES
  ('ruangrapi', 10, 'RuangRapi', 'Personal project', '2026', 'Rental operations SaaS for Indonesian landlords.', 'An operations system for owners of kos, kontrakan and small apartment portfolios: units, tenants, leases, monthly billing, payments, receipts, WhatsApp reminders, utility readings and maintenance tickets. Built as a modular monolith on Supabase with row-level security, specified domain-first and developed in small, reviewable agent-assisted steps.', '["React","TypeScript","Supabase","PostgreSQL","TanStack Query","Zod"]', '#00ff87', 'https://github.com/fitzfitz/ruangrapi'),
  ('portfolio', 20, 'This Flight-Sim CV', 'Personal project', '2026', 'The 3D portfolio you are flying through right now.', 'The real Solar System in React Three Fiber, every planet on its NASA JPL orbit for the date shown, with a chase-cam flight model, probe dossiers you grab with a tractor beam and a HUD that updates without React re-renders. Models are generated by scripted Blender and compressed with gltf-transform; behaviour is pinned by unit tests and end-to-end probes that drive a real Chrome, including draw-call and shader-program budgets.', '["React 19","TypeScript","three.js","React Three Fiber","Blender (bpy)","Vitest"]', '#00f0ff', 'https://github.com/fitzfitz/3d-portfolio'),
  ('fuxx', 30, 'fuxx', 'Personal project', '2026', 'GPU-accelerated terminal for running AI coding agents.', 'A native terminal that runs several AI coding agents in one window. Each session shows whether its agent is working, done or waiting for input, with a status badge and a desktop notification when a background session needs attention — so you can step away instead of watching a wall of terminals. Early and in active development, macOS first.', '["Rust","GPUI"]', '#bd00ff', 'https://github.com/fitzfitz/fuxx-cli');

